"""Long-term memory: every fact carries the window in which it is true."""

from datetime import date

MEMORIES = []


def store_memory(text, embed, valid_until=None, supersedes=None):
    """Append a fact with the interval it is true for, and retire what it replaces."""
    if supersedes is not None:
        for m in MEMORIES:
            if m["id"] == supersedes:
                m["valid_until"] = date.today().isoformat()
    MEMORIES.append({
        "id": len(MEMORIES),
        "text": text,
        "vector": embed(text),
        "as_of": date.today().isoformat(),
        "valid_until": valid_until,
    })


def is_expired(memory, today=None):
    """A fact whose validity window has closed is not a candidate for recall."""
    today = today or date.today().isoformat()
    return memory["valid_until"] is not None and memory["valid_until"] < today


def recall_memories(query, embed, k=5):
    """Rank by similarity, but only over facts that are still valid today."""
    q = embed(query)
    live = [m for m in MEMORIES if not is_expired(m)]
    ranked = sorted(live, key=lambda m: -cosine(q, m["vector"]))
    return [m["text"] for m in ranked[:k]]


def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = sum(x * x for x in a) ** 0.5
    nb = sum(x * x for x in b) ** 0.5
    return dot / (na * nb or 1.0)
